#!/usr/bin/env bash
# Renders deploy/k8s/hopper.yaml from the Helm chart, the only source of
# hopper's Kubernetes objects. With "-" it writes to stdout instead, which is
# what TestRenderedManifestsAreCurrent compares with the committed file.
set -euo pipefail
cd "$(dirname "$0")/.."

render() {
  cat <<'EOF'
# Generated by scripts/render-k8s.sh from deploy/helm/hopper with default
# values. Do not edit; change the chart and re-render with the Helm version
# test/chart names as canonicalHelm.
#
# The images are tagged with the chart's appVersion. Until Session 12 publishes
# them, build and load them on kind with: TAG=<appVersion> scripts/kind-up.sh
#
# The objects carry no namespace. Apply them into one that enforces the
# restricted Pod Security Standard and holds no Helm release of this chart.
# On the kind cluster (name your own context anywhere else):
#
#   kubectl --context kind-hopper create namespace hopper-plain
#   kubectl --context kind-hopper label namespace hopper-plain \
#     pod-security.kubernetes.io/enforce=restricted \
#     pod-security.kubernetes.io/enforce-version=v1.35
#   kubectl --context kind-hopper -n hopper-plain apply -f deploy/k8s/hopper.yaml
EOF
  helm template hopper deploy/helm/hopper --kube-version 1.35.8 --skip-tests
}

if [[ "${1:-}" == "-" ]]; then
  render
else
  mkdir -p deploy/k8s
  render > deploy/k8s/hopper.yaml
fi
